import ast,gzip,hashlib,json,subprocess,sys,collections
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path('/home/fenics/Projects/NN-Lab');D=ROOT/'docs/task042_neural_coarse_inverse';R=D/'outcomes/records';OUT=ROOT/'tmp/task042/review_v31'
HEAD='177ce7c645f14cedea65e8f309ed2c33b65978ed';BASE='bcd00052d45dd542830a64e182d5c480049dea23';SOURCE='a874498a1a8b854f394520627eaf09158b77fbf9'
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT)
def sha(b):return hashlib.sha256(b).hexdigest()
def read(n):return json.loads((R/n).read_text())
assert git('rev-parse','HEAD').decode().strip()==HEAD
verified={};skipped=[];archives=[]
def verify(x):
    if isinstance(x,dict):
        if isinstance(x.get('path'),str) and isinstance(x.get('sha256'),str):
            p=Path(x['path']);p=(p if p.is_absolute() else ROOT/p).resolve();assert p.is_relative_to(ROOT),p
            if p.suffix in ('.npz','.npy','.h5','.bin'):skipped.append(str(p));return
            b=p.read_bytes();assert sha(b)==x['sha256'],p
            if 'bytes' in x:assert len(b)==x['bytes'],p
            verified[str(p)]=dict(sha256=sha(b),bytes=len(b))
        if 'original_path' in x and 'archive' in x:
            p=Path(x['archive']['path']);p=p if p.is_absolute() else ROOT/p
            raw=gzip.decompress(p.read_bytes());assert sha(raw)==x['original_sha256'] and len(raw)==x['original_bytes']
            assert raw==Path(x['original_path']).read_bytes(),x['original_path'];archives.append(str(p))
        if 'original' in x and 'gzip' in x:
            original=x['original'];packed=x['gzip'];raw=gzip.decompress(Path(packed['path']).read_bytes())
            assert raw==Path(original['path']).read_bytes() and sha(raw)==original['sha256'] and len(raw)==original['bytes']
            archives.append(packed['path'])
        for v in x.values():verify(v)
    elif isinstance(x,list):
        for v in x:verify(v)
for n in ('source_inventory_v33.json','evidence_integrity_v33.json','raw_evidence_index_v33.json','input_inventory_v33.json','run_index_v33.json'):verify(read(n))
source=read('source_inventory_v33.json');assert source['actual_numeric_source'] is None
for row in source['tracked_implementation_files']:assert (ROOT/row['path']).read_bytes()==git('show',SOURCE+':'+row['path'])
changed=git('diff','--name-only',BASE,HEAD).decode().splitlines();compiled=[]
for p in changed:
    if p.endswith('.py'):compile((ROOT/p).read_text(),p,'exec');compiled.append(p)
history=[p for p in git('ls-tree','-r','--name-only',BASE,str(D.relative_to(ROOT))).decode().splitlines() if Path(p).name.startswith(('review_report_v','response_v'))]
for p in history:assert git('show',BASE+':'+p)==(ROOT/p).read_bytes(),p
suffix=[]
for rel in ('README.md','outcomes/summary.md','outcomes/test_summary.md','outcomes/changed_files.md'):
    p=str((D/rel).relative_to(ROOT));assert (ROOT/p).read_bytes().endswith(git('show',BASE+':'+p));suffix.append(p)
integrity=read('evidence_integrity_v33.json')
for p,row in integrity['protected_documents_and_compact_records'].items():
    raw=(ROOT/p).read_bytes();assert sha(raw)==row['sha256'] and len(raw)==row['bytes'],p
    assert raw==git('show',BASE+':'+p),p
    verified[str(ROOT/p)]=dict(sha256=sha(raw),bytes=len(raw))
for row in integrity['old_closed_files_unchanged']:
    if Path(row['path']).name=='ledger.json':assert json.loads(Path(row['path']).read_text())['closed']
book=read('ledger_v33.json');assert book==json.loads((ROOT/'tmp/task042/v33/ledger.json').read_text())
assert book['closed'] and book['active'] is None and not book['runs'] and not any(book['charged'].values())
d=json.loads(gzip.decompress((R/'raw_admission_json_v33.gz').read_bytes()))
fractions={int(k):v for k,v in d['cpu_busy_fractions'].items()}
for key,b in d['cpu_ticks_before'].items():
    a=d['cpu_ticks_after'][key];assert abs(1-(a[3]-b[3]+a[4]-b[4])/max(sum(a)-sum(b),1)-fractions[int(key)])<1e-15
for tid,a in d['thread_ticks_after'].items():
    b=d['thread_ticks_before'].get(tid)
    if b and a[0]==b[0]:assert d['thread_delta_ticks'][tid]==a[1]-b[1]
reasons={}
for cpu,v in fractions.items():
    if v>.05:reasons.setdefault(cpu,[]).append('sample_busy_fraction_gt_0.05')
for proc in d['neighbor_processes']:
    for t in proc['threads']:
        if len(t['affinity'])<=16:
            for cpu in t['affinity']:reasons.setdefault(cpu,[]).append('narrow_thread_affinity:'+str(t['tid']))
        elif d['thread_delta_ticks'].get(str(t['tid']),1)>0:reasons.setdefault(t['cpu'],[]).append('active_wide_thread:'+str(t['tid']))
decisions=[dict(**t,eligible=not any(c in reasons for c in t['siblings']),excluded_siblings={str(c):reasons[c] for c in t['siblings'] if c in reasons}) for t in d['topology']]
assert decisions==d['cpu_decisions'];assert [t['cpu'] for t in decisions if t['eligible']]==d['candidate_cpus']==[]
cpu_reason_counts=dict(collections.Counter(k.split(':')[0] for c in decisions for v in c['excluded_siblings'].values() for k in v))
cost=read('resource_costs_v33.json');assert cost['cumulative_supervised_seconds']==cost['carried_supervised_seconds']==151.4889468078036
assert cost['remaining_of_600_seconds']==600-cost['cumulative_supervised_seconds'];assert cost['new_supervised_actor_seconds']==cost['new_supervised_auxiliary_seconds']==0
cleanup=read('storage_cleanup_v33.json');files=cleanup['files']
assert len(files)==509 and sum(x['bytes'] for x in files)==10786688
assert all(Path(x['path']).suffix=='.pyc' and not (ROOT/x['path']).exists() for x in files)
dot=git('show','3c7458fad7c002babac4e634be4788b664be9ee5:docs/task40extra_dot_parallel_cloud/README.md')
(OUT/'dot_README.md').write_bytes(dot)
out=dict(schema='task042.review31.independent.v1',UTC=datetime.now(timezone.utc).isoformat(),reviewed_HEAD=HEAD,previous_review=BASE,
    final_implementation=SOURCE,actual_numeric_source=None,changed_files=changed,compiled_files=compiled,
    verified_metadata=verified,metadata_mismatches=[],raw_archives_lossless=sorted(set(archives)),skipped_numeric_payloads=sorted(set(skipped)),
    old_review_response_files_unchanged=history,historical_suffixes=suffix,old_closed_files=len(integrity['old_closed_files_unchanged']),
    v33_zero_consumption_independently_checked=True,v33_CPU_replayed=dict(candidate_count=0,topology_count=len(decisions),reason_occurrences=cpu_reason_counts,gates=d['gates']),
    cost_recomputed=dict(carry=cost['cumulative_supervised_seconds'],remaining=cost['remaining_of_600_seconds'],probe_seconds=cost['admission_probe_monotonic_seconds']),
    review_runtime=json.loads((OUT/'result.json').read_text()),review_admission=json.loads((OUT/'admission.json').read_text()),
    dot_remote_SHA='3c7458fad7c002babac4e634be4788b664be9ee5',dot_README_sha256=sha(dot),
    no_physical_action=True,no_real_factor_reads=True,no_real_solves=True,no_QR_SVD=True,no_FE_or_training=True,
    web_rendered_view='NOT_VERIFIED: GitHub web fetch Cache miss',script=Path(__file__).read_text())
out['isolation']=json.loads((OUT/'isolation.json').read_text())
out['isolation_runtime']=json.loads((OUT/'isolation_supervision/result.json').read_text())
out['review_auxiliary_seconds']=out['review_runtime']['elapsed_seconds']+out['isolation_runtime']['elapsed_seconds']
out['next_carry_including_this_review_auxiliary']=cost['cumulative_supervised_seconds']+out['review_auxiliary_seconds']
out['next_remaining_of_600']=600-out['next_carry_including_this_review_auxiliary']
out['supervision_raw_hashes']={}
for rel in ('admission.json','junit.xml','result.json','supervision/worker.log','supervision/resources.jsonl',
            'isolation_supervision/admission.json','isolation_supervision/result.json','isolation_supervision/supervision/worker.log','isolation_supervision/supervision/resources.jsonl'):
    p=OUT/rel
    if p.exists():out['supervision_raw_hashes'][rel]=dict(sha256=sha(p.read_bytes()),bytes=p.stat().st_size)
(OUT/'audit.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(dict(metadata_files=len(verified),metadata_bytes=sum(x['bytes'] for x in verified.values()),archives=len(set(archives)),changed_files=len(changed),compiled_files=len(compiled),old_documents=len(history),cpu=out['v33_CPU_replayed'],review_runtime=out['review_runtime']),ensure_ascii=False,indent=2))
